from pathlib import Path
Path('system').mkdir(exist_ok=True)
foam_header='''FoamFile
{
    format ascii;
    class dictionary;
    object %s;
}
'''
Path('system/controlDict').write_text(foam_header%'controlDict' + '''application checkMesh;
startFrom startTime;
startTime 0;
stopAt endTime;
endTime 1;
deltaT 1;
writeControl timeStep;
writeInterval 1;
''')
Path('system/fvSchemes').write_text(foam_header%'fvSchemes' + '''ddtSchemes { default steadyState; }
gradSchemes { default Gauss linear; }
divSchemes { default none; }
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected; }
''')
Path('system/fvSolution').write_text(foam_header%'fvSolution' + '''solvers {}
''')
print('wrote utility dictionaries:',*[str(p) for p in Path('system').iterdir()])

